import java.math.BigDecimal
import java.math.RoundingMode
import java.util.NoSuchElementException

class Ledger {
    private val balances = HashMap<String, BigDecimal>()
    private val log = HashMap<String, MutableList<BigDecimal>>()

    fun openAccount(id: String, initial: BigDecimal = BigDecimal.ZERO) {
        if (balances.containsKey(id)) {
            throw IllegalArgumentException("Account $id already exists")
        }
        // Validate that initial is positive or zero? The spec says "Amounts must be positive" but initial can be ZERO.
        // Let's assume initial >= 0. Also ensure it has at most 2 decimal places.
        require(initial.scale() <= 2) { "Initial amount must have at most 2 decimal places" }
        require(initial >= BigDecimal.ZERO) { "Initial amount must be non-negative" }

        balances[id] = initial.setScale(2, RoundingMode.HALF_UP)
        log[id] = mutableListOf()
    }

    fun balance(id: String): BigDecimal {
        val b = balances[id] ?: throw NoSuchElementException("Account $id not found")
        return b.setScale(2, RoundingMode.HALF_UP)
    }

    fun transfer(from: String, to: String, amount: BigDecimal) {
        // Validate amount is positive
        require(amount > BigDecimal.ZERO) { "Transfer amount must be positive" }
        // Ensure at most 2 decimal places
        require(amount.scale() <= 2) { "Amount must have at most 2 decimal places" }

        val fromBal = balances[from] ?: throw NoSuchElementException("Account $from not found")
        val toBal = balances[to] ?: throw NoSuchElementException("Account $to not found")

        // Check if sufficient funds
        if (fromBal < amount) {
            throw IllegalStateException("insufficient funds")
        }

        // Perform the transfer atomically: update both or neither.
        // Since we already checked, we can safely update.
        val newFromBal = fromBal - amount
        val newToBal = toBal + amount

        balances[from] = newFromBal
        balances[to] = newToBal

        log.getValue(from).add(-amount)
        log.getValue(to).add(amount)
    }

    fun history(id: String): List<BigDecimal> {
        val entries = log[id] ?: throw NoSuchElementException("Account $id not found")
        return entries.map { it.setScale(2, RoundingMode.HALF_UP) }
    }

    companion object {
        fun split(total: BigDecimal, n: Int): List<BigDecimal> {
            require(n > 0) { "Number of parts must be positive" }
            require(total >= BigDecimal.ZERO) { "Total must be non-negative" }

            if (n == 1) return listOf(total.setScale(2, RoundingMode.HALF_UP))

            // Divide total by n using HALF_UP rounding to get the base part
            val basePart = total.divide(BigDecimal(n), 2, RoundingMode.HALF_UP)

            // Calculate the remainder to distribute
            val distributedTotal = basePart * BigDecimal(n)
            var remainder = total - distributedTotal

            // We want larger parts first. The remainder is positive (or zero).
            // Each cent of remainder will be added to one part, making it larger by 0.01.
            // Since we want larger parts first, the first 'remainder' number of parts should be basePart + 0.01?
            // Wait: if total = 10, n=3. base = 3.33 (HALF_UP). distributed = 9.99. remainder = 0.01.
            // Parts: 3.34, 3.33, 3.33 -> sum = 10.00. Larger parts first means 3.34 comes first. Correct.

            // Another example: total=10, n=3. If we used DOWN: base=3.33, dist=9.99, rem=0.01. Same result.
            // Example: total=100, n=3. base=33.33 (HALF_UP). dist=99.99. rem=0.01. Parts: 33.34, 33.33, 33.33. Sum=100.
            // Example: total=10, n=6. base=1.67 (HALF_UP). dist=10.02. rem=-0.02. This is problematic with HALF_UP.

            // Let's use a more robust approach:
            // Use division with DOWN rounding to get the floor part.
            val unit = total.divide(BigDecimal(n), 2, RoundingMode.DOWN)
            var remainderAmount = total - unit * BigDecimal(n)

            // remainderAmount is >= 0 and < n * 0.01 (actually < 1.00 effectively since we're dealing with cents)
            // Actually, remainderAmount will be between 0 and n*0.01 roughly? No.
            // unit is floor(total/n). So remainder = total - n*unit. 
            // Since unit <= total/n, n*unit <= total, so remainder >= 0.
            // Also, if we incremented unit by 0.01, (n)*unit would exceed total? Not necessarily.
            // The key is: we need to distribute `remainderAmount` cents among `n` parts.
            // Each part gets `unit`. Then the first `remainderAmount / 0.01` parts get an extra 0.01.

            val numExtra = remainderAmount.divide(BigDecimal("0.01"), 0, RoundingMode.DOWN).toInt()
            require(numExtra < n) { "Internal error in split calculation" } // Should always hold

            val result = mutableListOf<BigDecimal>()
            for (i in 0 until n) {
                if (i < numExtra) {
                    result.add(unit + BigDecimal("0.01"))
                } else {
                    result.add(unit)
                }
            }

            // Verify sum
            val sum = result.sumOf { it }
            require(sum == total.setScale(2, RoundingMode.HALF_UP)) { "Split sum mismatch" }

            return result
        }
    }
}
