import java.util.LinkedHashMap

class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        if (capacity < 1) {
            throw IllegalArgumentException("Capacity must be >= 1")
        }
    }

    private val map = object : LinkedHashMap<K, V>(capacity, 0.75f, true) {
        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<K, V>): Boolean {
            return size > capacity
        }

        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<K, V>) {
            // We handle eviction ourselves to call onEvict, so we never auto-remove.
            // But LinkedHashMap's default behavior is to not remove. We need to manually evict when size exceeds capacity.
            // Actually, let's just override put and handle eviction there, or use a custom approach.
            // The standard way with LinkedHashMap(true) for access-order is to rely on removeEldestEntry.
            // But we need to call onEvict. So let's do it manually in set.
        }
    }

    // We'll implement our own eviction logic in set() to properly call onEvict.
    // So we won't use the automatic removal of LinkedHashMap.
    private val internalMap = object : LinkedHashMap<K, V>(capacity, 0.75f, true) {
        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<K, V>): Boolean {
            return false // We handle eviction manually
        }
    }

    operator fun get(key: K): V? {
        return internalMap[key]
    }

    operator fun set(key: K, value: V) {
        if (internalMap.containsKey(key)) {
            // Update existing key - this automatically moves it to most recently used in LinkedHashMap with access-order
            internalMap[key] = value
        } else {
            // Insert new key
            if (internalMap.size >= capacity) {
                // Evict least recently used
                val eldest = internalMap.entries.firstOrNull()
                if (eldest != null) {
                    onEvict(eldest.key, eldest.value)
                    internalMap.remove(eldest.key)
                }
            }
            internalMap[key] = value
        }
    }

    fun remove(key: K): V? {
        return internalMap.remove(key)
    }

    val size: Int
        get() = internalMap.size

    fun keys(): List<K> {
        // LinkedHashMap with access-order true iterates from least recently used to most recently used
        return internalMap.keys.toList()
    }

    operator fun contains(key: K): Boolean {
        return internalMap.containsKey(key)
    }
}
