```kotlin
fun toJson(value: Any?, indent: Int = 0): String {
    return buildString {
        appendValue(value, indent, 0)
    }
}

private fun StringBuilder.appendValue(value: Any?, indent: Int, level: Int) {
    when (value) {
        null -> append("null")
        is Boolean -> append(value)
        is String -> appendString(value)
        is Int -> append(value)
        is Long -> append(value)
        is Double -> appendDouble(value)
        is Float -> appendDouble(value.toDouble())
        is Map<*, *> -> appendMap(value, indent, level)
        is List<*> -> appendList(value, indent, level)
        is Array<*> -> appendList(value.toList(), indent, level)
        is Enum<*> -> append("\"${value.name}\"")
        else -> throw IllegalArgumentException("Unsupported type: ${value::class.java}")
    }
}

private fun StringBuilder.appendString(value: String) {
    append('"')
    for (c in value) {
        when (c) {
            '"' -> append("\\\"")
            '\\' -> append("\\\\")
            '\b' -> append("\\b")
            '\f' -> append("\\f")
            '\n' -> append("\\n")
            '\r' -> append("\\r")
            '\t' -> append("\\t")
            else -> {
                val code = c.code
                if (code < 0x20) {
                    append("\\u%04x".format(code))
                } else {
                    append(c)
                }
            }
        }
    }
    append('"')
}

private fun StringBuilder.appendDouble(value: Double) {
    if (value.isNaN() || value.isInfinite()) {
        throw IllegalArgumentException("Non-finite double value: $value")
    }
    // Kotlin's toString for Double handles the format we want.
    // However, we need to ensure that integers stored as Double are printed with a decimal point?
    // The requirement says: "a `Double` like `2.0` prints `2.0`". Kotlin's 2.0.toString() is "2.0".
    // It also says: "Use Kotlin's `toString()` for doubles (e.g. `1.0E-5` stays as Kotlin prints it)."
    append(value.toString())
}

private fun StringBuilder.appendMap(value: Map<*, *>, indent: Int, level: Int) {
    if (value.isEmpty()) {
        append("{}")
        return
    }

    val keys = value.keys.toList()
    // Check for non-String keys
    for (key in keys) {
        if (key !is String) {
            throw IllegalArgumentException("Map keys must be Strings, found: ${key::class.java}")
        }
    }

    if (indent == 0) {
        append("{")
        var first = true
        for (key in keys) {
            if (!first) append(",")
            first = false
            appendString(key as String)
            append(":")
            appendValue(value[key], indent, level + 1)
        }
        append("}")
    } else {
        val currentIndent = " ".repeat(level * indent)
        val nextIndent = " ".repeat((level + 1) * indent)

        append("{\n")
        var first = true
        for (key in keys) {
            if (!first) append(",\n")
            first = false
            append(nextIndent)
            appendString(key as String)
            append(": ")
            appendValue(value[key], indent, level + 1)
        }
        append("\n")
        append(currentIndent)
        append("}")
    }
}

private fun StringBuilder.appendList(value: List<*>, indent: Int, level: Int) {
    if (value.isEmpty()) {
        append("[]")
        return
    }

    if (indent == 0) {
        append("[")
        var first = true
        for (item in value) {
            if (!first) append(",")
            first = false
            appendValue(item, indent, level + 1)
        }
        append("]")
    } else {
        val currentIndent = " ".repeat(level * indent)
        val nextIndent = " ".repeat((level + 1) * indent)

        append("[\n")
        var first = true
        for (item in value) {
            if (!first) append(",\n")
            first = false
            append(nextIndent)
            appendValue(item, indent, level + 1)
        }
        append("\n")
        append(currentIndent)
        append("]")
    }
}
