sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}

class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val len = input.length

    // Helper to check if the previous token allows a leading minus for a number
    fun canHaveLeadingMinus(): Boolean {
        return tokens.isEmpty() || tokens.last() is Token.Op || (tokens.last() is Token.Paren && tokens.last().open)
    }

    while (i < len) {
        val c = input[i]

        // Skip whitespace
        if (c == ' ' || c == '\t' || c == '\n') {
            i++
            continue
        }

        val startPos = i

        // Parentheses
        if (c == '(') {
            tokens.add(Token.Paren(true, startPos))
            i++
            continue
        }
        if (c == ')') {
            tokens.add(Token.Paren(false, startPos))
            i++
            continue
        }

        // String literals
        if (c == '"' || c == '\'') {
            val quoteChar = c
            i++ // skip opening quote
            val sb = StringBuilder()
            while (i < len) {
                val ch = input[i]
                if (ch == '\\') {
                    i++
                    if (i >= len) {
                        throw TokenizeException("Unterminated string escape", startPos)
                    }
                    val nextCh = input[i]
                    when (nextCh) {
                        'n' -> sb.append('\n')
                        '\\' -> sb.append('\\')
                        '\'' -> sb.append('\'')
                        '"' -> sb.append('"')
                        else -> sb.append(nextCh)
                    }
                    i++
                } else if (ch == quoteChar) {
                    i++ // skip closing quote
                    break
                } else {
                    sb.append(ch)
                    i++
                }
            }
            if (i >= len && (input.lastIndex < 0 || input[len - 1] != quoteChar)) {
                // Check if we broke out of the loop because of closing quote or end of string
                // If we reached here, it means we didn't find the closing quote.
                // Note: The loop breaks on closing quote OR end of string.
                // If i == len, we ran out of characters without finding the quote.
                if (i >= len) {
                    throw TokenizeException("Unterminated string", startPos)
                }
            }
            tokens.add(Token.Str(sb.toString(), startPos))
            continue
        }

        // Numbers and Identifiers and Operators start with specific chars
        if (c.isDigit()) {
            i++
            val sb = StringBuilder()
            sb.append(c)
            var hasDot = false
            while (i < len && input[i].isDigit()) {
                sb.append(input[i])
                i++
            }
            if (i < len && input[i] == '.') {
                // Check for 5. case or .5 case
                // We already consumed digits before the dot.
                // If there are no digits after the dot, it's an error (5.)
                // But wait, what about .5? The current char is '.', so we must have started with a digit.
                // So this branch handles X.Y where X has at least one digit.
                i++ // skip dot
                hasDot = true
                var hasDigitsAfterDot = false
                while (i < len && input[i].isDigit()) {
                    sb.append(input[i])
                    i++
                    hasDigitsAfterDot = true
                }
                if (!hasDigitsAfterDot) {
                    throw TokenizeException("Malformed number: trailing dot", startPos)
                }
            }
            // Check for invalid sequence like .5 starting with a digit? No, .5 starts with '.'.
            // What about just "."? Handled by operator/unknown check below if it doesn't match a number start.

            try {
                val num = sb.toString().toDouble()
                tokens.add(Token.Num(num, startPos))
            } catch (e: NumberFormatException) {
                throw TokenizeException("Malformed number", startPos)
            }
            continue
        }

        if (c == '.' && !input.substring(startPos).startsWith('.')) { // Just a dot, not part of identifier starting with dot?
             // Wait, identifiers can have dots AFTER the first char.
             // So if we are at a '.', it cannot be the start of an identifier.
             // Can it be the start of a number? Only .5 is valid for numbers, but our number parsing above requires starting with a digit.
             // So a standalone '.' is not a valid token start for Number or Ident.
             // It might be part of an operator? No.
             // Is it an error? Or could it be start of .5?
             // The spec says: `.5` and `5.` are errors.
             // So if we see a '.', it's either part of an identifier (if previous token allowed) or an error?
             // No, identifiers `[A-Za-z_][A-Za-z0-9_.]*`. So an identifier cannot START with '.'.
             // Numbers: optional leading `-` ... digits with optional fraction. `.5` is explicitly an error. `5.` is explicitly an error.
             // So a standalone '.' is never a valid token start. It should be an error?
             // Let's look at the operators: `== != <= >= < > && || !`. No dot in operators.
             // So a standalone dot is an invalid character sequence.
             throw TokenizeException("Unexpected character '.'", startPos)
        }

        if (c == '-' && canHaveLeadingMinus()) {
            // It could be a negative number.
            // Check next char. If it's a digit, parse as number.
            // If it's not a digit, is it an operator? No, `-` alone is not an operator.
            // So if `-` is followed by non-digit, it's an error.
            if (i + 1 < len && input[i + 1].isDigit()) {
                i++ // skip minus
                val sb = StringBuilder()
                sb.append('-')
                while (i < len && input[i].isDigit()) {
                    sb.append(input[i])
                    i++
                }
                if (i < len && input[i] == '.') {
                    i++ // skip dot
                    var hasDigitsAfterDot = false
                    while (i < len && input[i].isDigit()) {
                        sb.append(input[i])
                        i++
                        hasDigitsAfterDot = true
                    }
                    if (!hasDigitsAfterDot) {
                        throw TokenizeException("Malformed number: trailing dot", startPos)
                    }
                }
                try {
                    val num = sb.toString().toDouble()
                    tokens.add(Token.Num(num, startPos))
                } catch (e: NumberFormatException) {
                    throw TokenizeException("Malformed number", startPos)
                }
                continue
            } else {
                // `-` not followed by digit. Not an operator. Error.
                throw TokenizeException("Unexpected character '-'", startPos)
            }
        }

        // Identifiers and Operators
        // Try to match longest operator first
        val remaining = input.substring(startPos)

        var matchedOp: String? = null
        if (remaining.startsWith("==")) matchedOp = "=="
        else if (remaining.startsWith("!=")) matchedOp = "!="
        else if (remaining.startsWith("<=")) matchedOp = "<="
        else if (remaining.startsWith(">=")) matchedOp = ">="
        else if (remaining.startsWith("&&")) matchedOp = "&&"
        else if (remaining.startsWith("||")) matchedOp = "||"
        else if (remaining.startsWith("!")) matchedOp = "!"
        else if (remaining.startsWith("<")) matchedOp = "<"
        else if (remaining.startsWith(">")) matchedOp = ">"

        if (matchedOp != null) {
            tokens.add(Token.Op(matchedOp, startPos))
            i += matchedOp.length
            continue
        }

        // If not an operator, try identifier
        // Identifiers: `[A-Za-z_][A-Za-z0-9_.]*`
        if (c.isLetter() || c == '_') {
            val sb = StringBuilder()
            sb.append(c)
            i++
            while (i < len && input[i].isLetterOrDigit() || input[i] == '.' || input[i] == '_') {
                // Dot is allowed after first char
                if (input[i] == '.') {
                    // Ensure it's not the start of a number or something else? 
                    // Since we already checked for digits and dots at start, this is safe.
                    sb.append(input[i])
                    i++
                } else {
                    sb.append(input[i])
                    i++
                }
            }
            tokens.add(Token.Ident(sb.toString(), startPos))
            continue
        }

        // If we get here, it's an invalid character
        throw TokenizeException("Unexpected character '$c'", startPos)
    }

    return tokens
}
