from datetime import datetime, timedelta
import calendar


def _parse_field(field_str: str, min_val: int, max_val: int, name_map: dict = None) -> list:
    """
    Parse a single cron field string and return a sorted list of valid integer values.

    Args:
        field_str: The cron field string (e.g., "*/5", "1-3,5", "JAN-MAR")
        min_val: Minimum allowed value for the field
        max_val: Maximum allowed value for the field
        name_map: Optional mapping from names to values (e.g., {"JAN": 1, "FEB": 2, ...})

    Returns:
        Sorted list of integers representing the valid values for this field.

    Raises:
        ValueError: If the field string is invalid.
    """
    if name_map is None:
        name_map = {}

    # Create reverse mapping for lookup
    value_to_name = {v: k.upper() for k, v in name_map.items()}

    result = set()
    parts = field_str.split(',')

    for part in parts:
        if not part:
            raise ValueError(f"Empty item in field")

        # Check for step
        step = None
        if '/' in part:
            range_part, step_str = part.split('/', 1)
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step value: {step_str}")
            if step <= 0:
                raise ValueError(f"Step must be positive, got {step}")
        else:
            range_part = part

        # Parse the range or single value
        if range_part == '*':
            start = min_val
            end = max_val
        elif '-' in range_part:
            range_parts = range_part.split('-', 1)
            if len(range_parts) != 2:
                raise ValueError(f"Invalid range: {range_part}")
            try:
                start_str, end_str = range_parts
                start = _resolve_value(start_str, min_val, max_val, name_map)
                end = _resolve_value(end_str, min_val, max_val, name_map)
            except ValueError as e:
                raise ValueError(f"Invalid range values in {range_part}: {e}")
            if start > end:
                raise ValueError(f"Range start ({start}) > end ({end}) in {range_part}")
        else:
            # Single value
            try:
                val = _resolve_value(range_part, min_val, max_val, name_map)
            except ValueError as e:
                raise ValueError(f"Invalid value {range_part}: {e}")
            if step is not None:
                # A/S means from A to max with step S
                start = val
                end = max_val
            else:
                result.add(val)
                continue

        # Generate values from start to end with step
        if step is None:
            # No step, just the range (or single value handled above)
            for v in range(start, end + 1):
                result.add(v)
        else:
            for v in range(start, end + 1, step):
                result.add(v)

    if not result:
        raise ValueError(f"Field produced no valid values")

    return sorted(result)


def _resolve_value(val_str: str, min_val: int, max_val: int, name_map: dict) -> int:
    """
    Resolve a single value string to an integer.

    Args:
        val_str: The value string (e.g., "5", "JAN")
        min_val: Minimum allowed value
        max_val: Maximum allowed value
        name_map: Name to value mapping

    Returns:
        The resolved integer value.

    Raises:
        ValueError: If the value is invalid.
    """
    if not val_str:
        raise ValueError("Empty value")

    # Check if it's a name
    upper_val = val_str.upper()
    if upper_val in name_map:
        return name_map[upper_val]

    # Try as integer
    try:
        val = int(val_str)
    except ValueError:
        raise ValueError(f"Unknown name or invalid number: {val_str}")

    if val < min_val or val > max_val:
        raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")

    return val


# Name mappings
MONTH_NAMES = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4,
    'MAY': 5, 'JUN': 6, 'JUL': 7, 'AUG': 8,
    'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
}

DAY_NAMES = {
    'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3,
    'THU': 4, 'FRI': 5, 'SAT': 6
}


def _parse_cron_field(field_str: str, field_name: str) -> list:
    """
    Parse a specific cron field with appropriate constraints and name mappings.
    """
    if field_name == 'month':
        return _parse_field(field_str, 1, 12, MONTH_NAMES)
    elif field_name == 'day_of_week':
        # Day of week: 0-7, but we normalize 7 to 0 (both are Sunday)
        values = _parse_field(field_str, 0, 7, DAY_NAMES)
        # Normalize 7 to 0
        normalized = set()
        for v in values:
            if v == 7:
                normalized.add(0)
            else:
                normalized.add(v)
        return sorted(normalized)
    elif field_name == 'day_of_month':
        return _parse_field(field_str, 1, 31)
    elif field_name == 'hour':
        return _parse_field(field_str, 0, 23)
    elif field_name == 'minute':
        return _parse_field(field_str, 0, 59)
    else:
        raise ValueError(f"Unknown field name: {field_name}")


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """
    Calculate the next fire time for a cron expression strictly after `after`.

    Args:
        expr: A standard 5-field cron expression.
        after: A naive datetime object.

    Returns:
        The earliest datetime strictly after `after` that matches the cron expression.

    Raises:
        ValueError: If the expression is invalid or no match is found within 5 years.
    """
    if not isinstance(after, datetime):
        raise TypeError("after must be a datetime object")

    # Parse the expression
    parts = expr.strip().split()
    if len(parts) != 5:
        raise ValueError(f"Expected 5 fields in cron expression, got {len(parts)}")

    minute_str, hour_str, dom_str, month_str, dow_str = parts

    try:
        minutes = _parse_cron_field(minute_str, 'minute')
        hours = _parse_cron_field(hour_str, 'hour')
        doms = _parse_cron_field(dom_str, 'day_of_month')
        months = _parse_cron_field(month_str, 'month')
        dows = _parse_cron_field(dow_str, 'day_of_week')
    except ValueError as e:
        raise ValueError(f"Invalid cron expression: {e}")

    # Determine if day-of-month and day-of-week are restricted
    dom_restricted = (dom_str.strip() != '*')
    dow_restricted = (dow_str.strip() != '*')

    # Start from the next minute after `after`
    candidate = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # We'll search for up to 5 years
    max_date = after + timedelta(days=365 * 5 + 2)  # Account for leap years

    # Optimization: iterate through months, then days, then hours, then minutes
    # But given the constraints, a simple iteration might be too slow if done naively.
    # Let's use a smarter approach: iterate through potential matching dates.

    current = candidate

    while current <= max_date:
        # Check month
        if current.month not in months:
            # Skip to the next valid month
            found_next_month = False
            for m in months:
                if m > current.month:
                    # Move to first day of that month at 00:00
                    try:
                        current = current.replace(year=current.year, month=m, day=1, hour=0, minute=0)
                    except ValueError:
                        continue
                    found_next_month = True
                    break
            if not found_next_month:
                # Move to next year, first valid month
                try:
                    next_year = current.year + 1
                    m = months[0]
                    current = current.replace(year=next_year, month=m, day=1, hour=0, minute=0)
                except ValueError:
                    pass
            continue

        # Check day (day-of-month and day-of-week)
        dom_match = current.day in doms
        dow_match = current.weekday()  # Python's weekday(): Monday=0, Sunday=6
        # Convert to cron's day of week: Sunday=0, Monday=1, ..., Saturday=6
        cron_dow = (current.weekday() + 1) % 7

        if dom_restricted and dow_restricted:
            # Either must match
            day_match = dom_match or (cron_dow in dows)
        else:
            # Both must match (if either is *, it always matches)
            day_match = dom_match and (cron_dow in dows) if dom_restricted else \
                        (dom_match and (cron_dow in dows)) if dow_restricted else \
                        dom_match and (cron_dow in dows)

        # Actually, let me re-read the rule:
        # "if both day-of-month and day-of-week are restricted (neither field is exactly *), 
        #  a day matches when EITHER matches. Otherwise both must match (a * always matches)."

        if dom_restricted and dow_restricted:
            day_match = dom_match or (cron_dow in dows)
        else:
            # At least one is not restricted (is *)
            # Both must match
            day_match = dom_match and (cron_dow in dows)

        if not day_match:
            # Skip to the next day
            try:
                current = current.replace(hour=0, minute=0) + timedelta(days=1)
            except ValueError:
                pass
            continue

        # Check hour
        if current.hour not in hours:
            # Find next valid hour today
            found_hour = False
            for h in hours:
                if h > current.hour:
                    try:
                        current = current.replace(hour=h, minute=minutes[0])
                    except ValueError:
                        continue
                    found_hour = True
                    break
            if not found_hour:
                # Move to next day
                try:
                    current = current.replace(hour=0, minute=0) + timedelta(days=1)
                except ValueError:
                    pass
            continue

        # Check minute
        if current.minute not in minutes:
            # Find next valid minute this hour
            found_minute = False
            for m in minutes:
                if m > current.minute:
                    current = current.replace(minute=m)
                    found_minute = True
                    break
            if not found_minute:
                # Move to next hour
                try:
                    current = current.replace(minute=0) + timedelta(hours=1)
                except ValueError:
                    pass
            continue

        # All fields match!
        return current

    raise ValueError("No matching time found within 5 years")
