def merge(base: dict, *overrides: dict) -> dict:
    """
    Deep merge configuration layers. Later overrides win.

    - Dicts are merged recursively.
    - Any other value in an override replaces the base value (lists are replaced, not concatenated).
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends: {"plugins+": ["x"]} appends items to the base list `plugins`.
      If the base value exists and is not a list, raise TypeError.
      The '+' key itself never appears in the result.
    - Inputs are not mutated; result shares no mutable dicts/lists with inputs (deep copy).
    """
    import copy

    def deep_copy(obj):
        return copy.deepcopy(obj)

    # Start with a deep copy of base to avoid mutating it
    result = deep_copy(base)

    for override in overrides:
        _merge_into(result, override)

    return result


def _merge_into(target: dict, source: dict):
    """Merge source into target in place. Source is not mutated."""
    import copy

    for key, value in source.items():
        if key.endswith('+'):
            # Append mode
            base_key = key[:-1]
            append_list = value

            if not isinstance(append_list, list):
                raise TypeError(f"Append operator '+' requires a list value for key '{key}'")

            if base_key in target:
                if not isinstance(target[base_key], list):
                    raise TypeError(f"Cannot append to non-list value for key '{base_key}'")
                # Append items to the existing list (deep copy each item to avoid sharing)
                for item in append_list:
                    target[base_key].append(copy.deepcopy(item))
            else:
                # Base doesn't exist, create new list with deep copied items
                target[base_key] = [copy.deepcopy(item) for item in append_list]
        elif value is None:
            # Delete key from result
            if key in target:
                del target[key]
        else:
            # Regular merge or replace
            if isinstance(value, dict) and key in target and isinstance(target[key], dict):
                # Recursively merge dicts
                _merge_into(target[key], value)
            else:
                # Replace with a deep copy of the value
                target[key] = copy.deepcopy(value)
