def flatten(obj, sep=".") -> dict:
    """
    Turns nested dicts and lists into a flat dict with path keys.

    - Dict keys are joined with `sep`.
    - List items use their index (`a.0.b`).
    - Empty dicts and empty lists are kept as leaf values.
    - Any other value is a leaf.
    - The top-level object must be a dict (else TypeError).
    - Keys must be strings that don't contain `sep` (else ValueError).
    - Order: depth-first, in the input's order.
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = {}

    def _flatten(current, path_parts):
        if isinstance(current, dict):
            if len(current) == 0:
                # Empty dict is a leaf value
                key = sep.join(path_parts)
                result[key] = current
                return
            for k, v in current.items():
                if not isinstance(k, str):
                    raise ValueError("Keys must be strings")
                if sep in k:
                    raise ValueError(f"Key '{k}' contains separator '{sep}'")
                _flatten(v, path_parts + [k])
        elif isinstance(current, list):
            if len(current) == 0:
                # Empty list is a leaf value
                key = sep.join(path_parts)
                result[key] = current
                return
            for i, v in enumerate(current):
                _flatten(v, path_parts + [str(i)])
        else:
            # Any other value is a leaf
            key = sep.join(path_parts)
            result[key] = current

    _flatten(obj, [])
    return result


def unflatten(flat: dict, sep=".") -> dict:
    """
    Inverse of flatten: turns a flat dict with path keys back into a nested structure.

    - A path segment that is a non-negative integer without leading zeros creates a list.
    - Lists must be dense: indices must be exactly 0..n-1 (else ValueError).
    - Conflicts such as {"a": 1, "a.b": 2} raise ValueError.
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    def _is_valid_list_index(s: str) -> bool:
        """Check if string is a non-negative integer without leading zeros."""
        if not s:
            return False
        # Check for leading zeros: "0" is valid, "00", "01", etc. are not
        if len(s) > 1 and s[0] == '0':
            return False
        try:
            val = int(s)
            return val >= 0
        except ValueError:
            return False

    def _to_list_index(s: str) -> int:
        return int(s)

    root = {}

    for path_key, value in flat.items():
        parts = path_key.split(sep) if path_key else []

        # Navigate/create the nested structure
        current = root

        for i, part in enumerate(parts):
            is_last = (i == len(parts) - 1)

            if _is_valid_list_index(part):
                idx = _to_list_index(part)

                # If current is a dict, we need to convert or check
                if isinstance(current, dict):
                    if part in current:
                        existing = current[part]
                        if not isinstance(existing, list):
                            raise ValueError(f"Conflict at key '{sep.join(parts[:i+1])}': expected list but found {type(existing).__name__}")
                        # It's already a list, use it
                    else:
                        # Create a new list. But we need to handle the case where 
                        # there might be dict children that conflict.
                        # Actually, if we're creating a list here, any existing dict child would be a conflict.
                        # But since we process in order, let's just create it.
                        # However, we need to ensure no conflicts with dict keys.
                        # The check for conflicts is handled by ensuring that if we later encounter a dict key 
                        # at this level, it doesn't exist as an integer index and vice versa.
                        current[part] = []

                if isinstance(current, list):
                    # Extend the list if needed to accommodate idx
                    while len(current) <= idx:
                        current.append(None)
                    if is_last:
                        current[idx] = value
                    else:
                        current = current[idx]
                        if current is None:
                            current = {}
                else:
                    raise ValueError(f"Expected list at path '{sep.join(parts[:i+1])}' but found {type(current).__name__}")
            else:
                # It's a string key (not a valid list index)
                if isinstance(current, list):
                    raise ValueError(f"Expected dict at path '{sep.join(parts[:i+1])}' but found list")

                if part in current:
                    existing = current[part]
                    if is_last:
                        # Conflict: we're trying to set a value where one already exists
                        raise ValueError(f"Conflict at key '{sep.join(parts[:i+1])}': key already exists")
                    else:
                        current = existing
                else:
                    if is_last:
                        current[part] = value
                    else:
                        # We need to create a new container. But we don't know yet if it should be dict or list.
                        # Look ahead to determine the type based on subsequent parts.
                        next_part = parts[i + 1]
                        if _is_valid_list_index(next_part):
                            current[part] = []
                        else:
                            current[part] = {}
                        current = current[part]

    return root
