                    raise ValueError("Keys must be strings")
                if sep in k:
                    raise ValueError(f"Key '{k}' contains separator '{sep}'")
                _flatten(v, path_parts + [k])
        elif isinstance(current, list):
            if len(current) == 0:
                # Empty list is a leaf value
                key = sep.join(path_parts)
                result[key] = current
                return
            for i, v in enumerate(current):
                _flatten(v, path_parts + [str(i)])
        else:
            # Any other value is a leaf
            key = sep.join(path_parts)
            result[key] = current

    _flatten(obj, [])
    return result


def unflatten(flat: dict, sep=".") -> dict:
    """
    Inverse of flatten: turns a flat dict with path keys back into a nested structure.

    - A path segment that is a non-negative integer without leading zeros creates a list.
    - Lists must be dense: indices must be exactly 0..n-1 (else ValueError).
    - Conflicts such as {"a": 1, "a.b": 2} raise ValueError.
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    def _is_valid_list_index(s: str) -> bool:
        """Check if string is a non-negative integer without leading zeros."""
        if not s:
            return False
        # Check for leading zeros: "0" is valid, "00", "01", etc. are not
        if len(s) > 1 and s[0] == '0':
            return False
        try:
            val = int(s)
            return val >= 0
        except ValueError:
            return False

    def _to_list_index(s: str) -> int:
        return int(s)

    root = {}

    for path_key, value in flat.items():
        parts = path_key.split(sep) if path_key else []

        # Navigate/create the nested structure
        current = root

        for i, part in enumerate(parts):
            is_last = (i == len(parts) - 1)

            if _is_valid_list_index(part):
                idx = _to_list_index(part)

                if isinstance(current, dict):
                    # Check if there's a conflict: the key exists as a string key but we need a list
                    # or vice versa. Actually, if current is a dict and we're trying to access an integer index,
                    # it means this level should be a list. But the current structure has dict keys.
                    # This is a conflict.
                    raise ValueError(f"Conflict at path '{sep.join(parts[:i+1])}': expected list but found dict")

                if isinstance(current, list):
                    # Extend the list if needed to accommodate idx
                    while len(current) <= idx:
                        current.append(None)
                    if is_last:
                        current[idx] = value
                    else:
                        if current[idx] is None:
                            # Determine what type to create based on next part
                            if i + 1 < len(parts):
                                next_part = parts[i + 1]
                                if _is_valid_list_index(next_part):
                                    current[idx] = []
                                else:
                                    current[idx] = {}
                            else:
                                # This shouldn't happen since is_last would be True
                                current[idx] = {}
                        current = current[idx]
                else:
                    raise ValueError(f"Expected list at path '{sep.join(parts[:i+1])}' but found {type(current).__name__}")
            else:
                # It's a string key (not a valid list index)
                if isinstance(current, list):
                    raise ValueError(f"Expected dict at path '{sep.join(parts[:i+1])}' but found list")

                if part in current:
                    existing = current[part]
                    if is_last:
                        # Conflict: we're trying to set a value where one already exists
                        raise ValueError(f"Conflict at key '{sep.join(parts[:i+1])}': key already exists")
                    else:
                        current = existing
                else:
                    if is_last:
                        current[part] = value
                    else:
                        # We need to create a new container. Look ahead to determine the type.
                        next_part = parts[i + 1]
                        if _is_valid_list_index(next_part):
                            current[part] = []
                        else:
                            current[part] = {}
                        current = current[part]

    # After building, verify that all lists are dense
    def _verify_lists(node):
        if isinstance(node, list):
            for i, item in enumerate(node):
                if item is not None:
                    _verify_lists(item)
            # Check density: all indices from 0 to len-1 must be present (not None)
            for i in range(len(node)):
                if node[i] is None:
                    raise ValueError(f"List at path is not dense: index {i} is missing")
        elif isinstance(node, dict):
            for v in node.values():
                _verify_lists(v)

    _verify_lists(root)

    return root
