import bisect


class IntervalSet:
    def __init__(self, intervals=()):
        self._iv = []
        for s, e in intervals:
            self.add(s, e)

    def add(self, start, end):
        if start >= end:
            return
        # Find the first interval that could overlap with [start, end)
        # An interval overlaps if its start < end and its end > start
        i = bisect.bisect_left(self._iv, (start,))
        # Check if the previous interval overlaps
        if i > 0 and self._iv[i - 1][1] > start:
            i -= 1
        j = i
        while j < len(self._iv) and self._iv[j][0] < end:
            start = min(start, self._iv[j][0])
            end = max(end, self._iv[j][1])
            j += 1
        self._iv[i:j] = [(start, end)]

    def remove(self, start, end):
        if start >= end:
            return
        out = []
        for s, e in self._iv:
            # No overlap case
            if e <= start or s >= end:
                out.append((s, e))
                continue
            # There is overlap. Split the interval.
            if s < start:
                out.append((s, start))
            if e > end:
                out.append((end, e))
        self._iv = out

    def contains(self, x):
        i = bisect.bisect_left(self._iv, (x,))
        # Check interval at i
        if i < len(self._iv) and self._iv[i][0] <= x < self._iv[i][1]:
            return True
        # Check previous interval
        if i > 0:
            prev_s, prev_e = self._iv[i - 1]
            if prev_s <= x < prev_e:
                return True
        return False

    def free(self, lo, hi):
        if lo >= hi:
            return []
        gaps = []
        cur = lo
        for s, e in self._iv:
            # Skip intervals that end before or at current position
            if e <= cur:
                continue
            # If interval starts after cur, we have a gap
            if s > cur:
                gap_end = min(s, hi)
                if cur < gap_end:
                    gaps.append((cur, gap_end))
                if s >= hi:
                    break
            # Advance cur past this interval
            cur = max(cur, e)
            if cur >= hi:
                break
        if cur < hi:
            gaps.append((cur, hi))
        return gaps

    def __iter__(self):
        return iter(self._iv)

    def __len__(self):
        return len(self._iv)
