    """Expand a tilde range like ~1.2.3."""
    ver = parse_version_partial(ver_str)

    # ~1.2.3 -> >=1.2.3 <1.3.0
    # ~1.2 -> >=1.2.0 <1.3.0
    # ~1 -> >=1.0.0 <2.0.0

    if ver.minor > 0 or ver.patch > 0:
        # If minor or patch is specified and non-zero, we can use the minor as upper bound
        upper_minor = ver.minor + 1
        upper = Version(ver.major, upper_minor, 0)
    else:
        # ~1.x or ~x -> >=major.0.0 <(major+1).0.0
        upper = Version(ver.major + 1, 0, 0)

    return [Comparator('>=', ver), Comparator('<', upper)]


def expand_caret(ver_str: str) -> List[Comparator]:
    """Expand a caret range like ^1.2.3."""
    ver = parse_version_partial(ver_str)
    major, minor, patch = ver.major, ver.minor, ver.patch

    if major != 0:
        # ^1.2.3 -> >=1.2.3 <2.0.0
        upper = Version(major + 1, 0, 0)
    elif minor != 0:
        # ^0.2.3 -> >=0.2.3 <0.3.0
        upper = Version(0, minor + 1, 0)
    else:
        # ^0.0.3 -> >=0.0.3 <0.0.4
        upper = Version(0, 0, patch + 1)

    return [Comparator('>=', ver), Comparator('<', upper)]


def expand_hyphen(lower_str: str, upper_str: str) -> List[Comparator]:
    """Expand a hyphen range like 1.2.3 - 2.3.4."""
    lower = parse_version_partial(lower_str)

    # Parse upper bound
    upper_parts = upper_str.strip().split('.')
    is_upper_partial = False
    upper_numeric = []
    for part in upper_parts:
        if part.lower() == 'x' or part == '*':
            upper_numeric.append(0)
            is_upper_partial = True
        else:
            if not re.match(r'^(0|[1-9]\d*)$', part):
                raise ValueError(f"Invalid version part in hyphen range: {part}")
            upper_numeric.append(int(part))

    while len(upper_numeric) < 3:
        upper_numeric.append(0)

    upper_major, upper_minor, upper_patch = upper_numeric[0], upper_numeric[1], upper_numeric[2]

    if is_upper_partial:
        # Partial upper bound: exclusive of the next patch/minor/major
        # 1.2.3 - 2.3 -> >=1.2.3 <2.4.0
        # Determine how many parts were specified in upper
        num_upper_parts = len([p for p in upper_parts if p.lower() != 'x' and p != '*'])

        if num_upper_parts == 1:
            # Like 2 -> >=lower <3.0.0
            upper = Version(upper_major + 1, 0, 0)
        elif num_upper_parts == 2:
            # Like 2.3 -> >=lower <2.4.0
            upper = Version(upper_major, upper_minor + 1, 0)
        else:
            # Should not happen if is_upper_partial is True and we have at least one wildcard
            # But if it's like 2.x, then num_upper_parts=1
            upper = Version(upper_major, upper_minor + 1, 0)
    else:
        # Exact upper bound: inclusive
        return [Comparator('>=', lower), Comparator('<=', Version(upper_major, upper_minor, upper_patch))]

    return [Comparator('>=', lower), Comparator('<', upper)]


def parse_range(rng: str) -> Range:
    """Parse an npm version range string."""
    rng = rng.strip()
    if not rng:
        raise ValueError("Empty range")

    # Split by ||
    sets_str = [s.strip() for s in rng.split('||')]

    comparator_sets = []
    for set_str in sets_str:
        if not set_str or set_str == '*':
            # Empty set or * matches any release
            comparator_sets.append(ComparatorSet([Comparator('>=', Version(0, 0, 0))]))
            continue

        # Split by whitespace to get individual comparators
        parts = set_str.split()

        comparators = []
        i = 0
        while i < len(parts):
            part = parts[i]

            # Check if it's a hyphen range
            if i + 2 < len(parts) and parts[i+1] == '-':
                lower_str = part
                upper_str = parts[i+2]
                comparators.extend(expand_hyphen(lower_str, upper_str))
                i += 3
                continue

            # Determine operator
            op = ''
            ver_str = part
            if part.startswith('>='):
                op = '>='
                ver_str = part[2:]
            elif part.startswith('<='):
                op = '<='
                ver_str = part[2:]
            elif part.startswith('>'):
                op = '>'
                ver_str = part[1:]
            elif part.startswith('<'):
                op = '<'
                ver_str = part[1:]
            elif part.startswith('='):
                op = '='
                ver_str = part[1:]

            # Check for tilde or caret
            if ver_str.startswith('~'):
                tilde_ver = ver_str[1:].strip()
                comparators.extend(expand_tilde(tilde_ver))
            elif ver_str.startswith('^'):
                caret_ver = ver_str[1:].strip()
                comparators.extend(expand_caret(caret_ver))
            else:
                # Could be an X-range or a partial version
                if 'x' in ver_str.lower() or '*' in ver_str:
                    comparators.extend(expand_x_range(ver_str))
                else:
                    comparators.extend(expand_comparator(op, ver_str))

            i += 1

        comparator_sets.append(ComparatorSet(comparators))

    return Range(comparator_sets)


def satisfies(version: str, rng: str) -> bool:
    """Check if a version satisfies a range."""
    v = Version.parse(version)
    r = parse_range(rng)
    return r.satisfies(v)


def max_satisfying(versions: list, rng: str) -> Optional[str]:
    """Return the highest version from the list that satisfies the range, or None."""
    if not versions:
        return None

    r = parse_range(rng)

    best_version = None
    best_original = None

    for ver_str in versions:
        try:
            v = Version.parse(ver_str)
        except ValueError:
            continue

        if r.satisfies(v):
            if best_version is None or v > best_version:
                best_version = v
                best_original = ver_str

    return best_original
