import re
from dataclasses import dataclass
from typing import List, Optional, Tuple


@dataclass(frozen=True)
class Prerelease:
    """Represents a SemVer prerelease string."""
    identifiers: list  # list of str or int

    def __lt__(self, other):
        if not isinstance(other, Prerelease):
            return NotImplemented
        return self._compare(self.identifiers, other.identifiers) < 0

    def __le__(self, other):
        if not isinstance(other, Prerelease):
            return NotImplemented
        return self._compare(self.identifiers, other.identifiers) <= 0

    def __gt__(self, other):
        if not isinstance(other, Prerelease):
            return NotImplemented
        return self._compare(self.identifiers, other.identifiers) > 0

    def __ge__(self, other):
        if not isinstance(other, Prerelease):
            return NotImplemented
        return self._compare(self.identifiers, other.identifiers) >= 0

    def __eq__(self, other):
        if not isinstance(other, Prerelease):
            return NotImplemented
        return self.identifiers == other.identifiers

    @staticmethod
    def _compare(a: list, b: list) -> int:
        """Compare two prerelease identifier lists."""
        for i in range(min(len(a), len(b))):
            ai, bi = a[i], b[i]
            a_is_int = isinstance(ai, int)
            b_is_int = isinstance(bi, int)
            if a_is_int and b_is_int:
                if ai < bi:
                    return -1
                elif ai > bi:
                    return 1
            elif a_is_int and not b_is_int:
                # Numeric identifiers always have lower precedence than alphanumeric
                return -1
            elif not a_is_int and b_is_int:
                return 1
            else:
                # Both strings, compare as ASCII
                if ai < bi:
                    return -1
                elif ai > bi:
                    return 1
        # If all compared identifiers are equal, shorter list is smaller
        if len(a) < len(b):
            return -1
        elif len(a) > len(b):
            return 1
        return 0


@dataclass(frozen=True)
class Version:
    """Represents a SemVer 2.0.0 version."""
    major: int
    minor: int
    patch: int
    prerelease: Optional[Prerelease] = None
    build: str = ""

    def __post_init__(self):
        # Ensure immutability of mutable fields
        if self.prerelease is not None:
            object.__setattr__(self, 'prerelease', Prerelease(list(self.prerelease.identifiers)))

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(self, other) < 0

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(self, other) <= 0

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(self, other) > 0

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(self, other) >= 0

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        # Build metadata is ignored for equality/precedence
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self._compare_pre(self.prerelease, other.prerelease) == 0)

    def __hash__(self):
        # Build metadata is ignored for hashing to match equality semantics
        return hash((self.major, self.minor, self.patch, self.prerelease))

    @staticmethod
    def _compare_pre(a: Optional[Prerelease], b: Optional[Prerelease]) -> int:
        """Compare prereleases. No prerelease > any prerelease."""
        if a is None and b is None:
            return 0
        if a is not None and b is None:
            # Prelease < release
            return -1
        if a is None and b is not None:
            return 1
        # Both have prereleases
        return Prerelease._compare(a.identifiers, b.identifiers)

    @staticmethod
    def _compare(a: 'Version', b: 'Version') -> int:
        """Compare two versions by SemVer precedence."""
        # Compare major.minor.patch
        for va, vb in [(a.major, b.major), (a.minor, b.minor), (a.patch, b.patch)]:
            if va < vb:
                return -1
            elif va > vb:
                return 1
        # Compare prerelease
        return Version._compare_pre(a.prerelease, b.prerelease)

    @staticmethod
    def parse(v: str) -> 'Version':
        """Parse a SemVer version string."""
        s = v.strip()
        if not s:
            raise ValueError("Empty version string")

        # Remove leading 'v' or '='
        if s.startswith('v') or s.startswith('='):
            s = s[1:]

        # Regex for SemVer 2.0.0
        # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
        pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'
        m = re.match(pattern, s)
        if not m:
            raise ValueError(f"Invalid SemVer version: {v}")

        major = int(m.group(1))
        minor = int(m.group(2))
        patch = int(m.group(3))
        prerelease_str = m.group(4)
        build = m.group(5) or ""

        prerelease = None
        if prerelease_str:
            identifiers = []
            for ident in prerelease_str.split('.'):
                if re.match(r'^\d+$', ident):
                    identifiers.append(int(ident))
                else:
                    identifiers.append(ident)
            prerelease = Prerelease(identifiers)

        return Version(major, minor, patch, prerelease, build)


class Comparator:
    """Represents a single comparator like >=1.2.3."""
    def __init__(self, op: str, version: Version):
        self.op = op
        self.version = version

    def satisfies(self, v: Version) -> bool:
        if self.op == '=':
            return v == self.version
        elif self.op == '<':
            return v < self.version
        elif self.op == '<=':
            return v <= self.version
        elif self.op == '>':
            return v > self.version
        elif self.op == '>=':
            return v >= self.version
        else:
            raise ValueError(f"Unknown operator: {self.op}")


class ComparatorSet:
    """A set of comparators that must all match."""
    def __init__(self, comparators: List[Comparator]):
        self.comparators = comparators

    def satisfies(self, v: Version) -> bool:
        # Check if any comparator has a prerelease with the same major.minor.patch as v
        has_comparator_with_same_patch_prerelease = False
        for comp in self.comparators:
            if comp.version.prerelease is not None:
                if (comp.version.major == v.major and
                    comp.version.minor == v.minor and
                    comp.version.patch == v.patch):
                    has_comparator_with_same_patch_prerelease = True
                    break

        # If the version being tested has a prerelease, it only satisfies if
        # some comparator in the set has a version with the same major.minor.patch and a prerelease.
        if v.prerelease is not None:
            if not has_comparator_with_same_patch_prerelease:
                return False

        # Check all comparators
        for comp in self.comparators:
            if not comp.satisfies(v):
                return False
        return True


