def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Implement a subset of POSIX shell word splitting and parameter expansion.

    Args:
        line: The command line string to parse.
        env: The environment variables for expansion.

    Returns:
        A list of words after parsing, expanding, and splitting.

    Raises:
        ValueError: For unterminated quotes, unterminated ${}, or trailing backslash.
    """

    def expand_variables(text: str, env: dict[str, str]) -> str:
        """Expand $NAME, ${NAME}, etc. in text."""
        result = []
        i = 0
        n = len(text)

        while i < n:
            if text[i] == '$':
                expanded, consumed = _expand_at(text, i, env)
                result.append(expanded)
                i += consumed
            else:
                result.append(text[i])
                i += 1

        return ''.join(result)

    def _expand_at(text: str, pos: int, env: dict[str, str]) -> tuple[str, int]:
        """
        Expand $ at position pos. Returns (expanded_text, chars_consumed).
        """
        if pos + 1 >= len(text):
            return ('$', 1)

        next_c = text[pos + 1]

        if next_c == '{':
            # ${...} form
            depth = 0
            j = pos + 2
            while j < len(text):
                if text[j] == '{':
                    depth += 1
                elif text[j] == '}':
                    if depth == 0:
                        break
                    else:
                        depth -= 1
                j += 1

            if j >= len(text):
                raise ValueError("Unterminated ${}")

            inner = text[pos + 2:j]
            chars_consumed = j - pos + 1

            # Parse variable name and modifier
            import re
            m = re.match(r'[A-Za-z_][A-Za-z0-9_]*', inner)
            if not m:
                return ('${', 2)  # Invalid, treat as literal

            var_name = inner[:m.end()]
            rest = inner[m.end():]

            default_value = None
            modifier_type = None

            if rest.startswith(':-'):
                modifier_type = ':-'
                default_text = rest[2:]
            elif rest.startswith('-'):
                modifier_type = '-'
                default_text = rest[1:]
            else:
                pass

            val = env.get(var_name, '')

            if modifier_type == ':-':
                if not val:
                    expanded_default = expand_variables(default_text, env)
                    return (expanded_default, chars_consumed)
                else:
                    return (val, chars_consumed)
            elif modifier_type == '-':
                if var_name not in env:
                    expanded_default = expand_variables(default_text, env)
                    return (expanded_default, chars_consumed)
                else:
                    return (val, chars_consumed)
            else:
                return (val, chars_consumed)

        elif next_c.isalpha() or next_c == '_':
            j = pos + 2
            while j < len(text) and (text[j].isalnum() or text[j] == '_'):
                j += 1
            var_name = text[pos + 1:j]
            chars_consumed = j - pos

            val = env.get(var_name, '')
            return (val, chars_consumed)
        else:
            return ('$', 1)

    def _parse_and_split(line: str, env: dict[str, str]) -> list[str]:
        """
        Parse line into words with proper quote and expansion handling.
        """

        # We'll parse character by character, building words.
        # Each word is a list of (text, quoted) segments.
        # At the end, we expand each word's text and split if not fully quoted.

        words = []  # List of (full_text: str, all_quoted: bool)
        current_word_parts = []  # List of (text: str, quoted: bool)
        in_single_quote = False
        in_double_quote = False

        i = 0
        n = len(line)

        def flush_current_word():
            if current_word_parts:
                full_text = ''.join([t for t, q in current_word_parts])
                all_quoted = all(q for t, q in current_word_parts)
                words.append((full_text, all_quoted))
                current_word_parts.clear()

        while i < n:
            c = line[i]

            if in_single_quote:
                if c == "'":
                    in_single_quote = False
                    i += 1
                else:
                    current_word_parts.append((c, True))
                    i += 1

            elif in_double_quote:
                if c == '\\':
                    if i + 1 >= n:
                        raise ValueError("Trailing backslash")
                    next_c = line[i + 1]
                    if next_c == '\n':
                        # Backslash-newline removed entirely
                        i += 2
                    elif next_c in ('$', '"', '\\'):
                        current_word_parts.append((next_c, True))
                        i += 2
                    else:
                        # Other backslash stays as is
                        current_word_parts.append(('\\', True))
                        i += 1
                elif c == '$':
                    # Expand $ inside double quotes
                    expanded, consumed = _expand_at(line, i, env)
                    current_word_parts.append((expanded, True))
                    i += consumed
                elif c == '"':
                    in_double_quote = False
                    i += 1
                else:
                    current_word_parts.append((c, True))
                    i += 1

            else:
                # Not in any quote
                if c == "'":
                    in_single_quote = True
                    i += 1
                elif c == '"':
                    in_double_quote = True
                    i += 1
                elif c == '\\':
                    if i + 1 >= n:
                        raise ValueError("Trailing backslash")
                    next_c = line[i + 1]
                    if next_c == '\n':
                        # Backslash-newline removed entirely
                        i += 2
                    else:
                        current_word_parts.append((next_c, False))
                        i += 2
                elif c in (' ', '\t', '\n'):
                    flush_current_word()
                    i += 1
                else:
                    current_word_parts.append((c, False))
                    i += 1

        # Check for unterminated quotes
        if in_single_quote:
            raise ValueError("Unterminated single quote")
        if in_double_quote:
            raise ValueError("Unterminated double quote")

        flush_current_word()

        # Now expand and split each word
        result = []
        for full_text, all_quoted in words:
            expanded = expand_variables(full_text, env)

            if all_quoted:
                # Don't split; add as-is (even if empty)
                result.append(expanded)
            else:
                # Split on whitespace
                parts = expanded.split()
                for part in parts:
                    result.append(part)

        return result

    return _parse_and_split(line, env)
