            # This won't work for arbitrary strings. We need to evaluate the string.
            # Better approach: resolve at the dataclass level and pass resolved types down.
            # For now, let's assume target_type is already resolved by the caller.
            raise LoadError(path, f"Cannot handle unresolved string type: {target_type}")
        except Exception:
            raise LoadError(path, f"Cannot evaluate type annotation: {target_type}")

    # Handle NoneType
    if target_type is type(None):
        if value is None:
            return None
        else:
            raise LoadError(path, f"Expected None, got {type(value).__name__}")

    # Handle Union types (including Optional which is Union[T, None])
    if origin is Union:
        # Try each member in order
        non_none_args = [a for a in args if a is not type(None)]
        none_arg = type(None) in args

        # If value is None and None is an option, return None
        if value is None and none_arg:
            return None

        # Try each non-None type
        errors = []
        for arg in args:
            if arg is type(None):
                continue
            try:
                return _load_value(value, arg, path, globalns, localns)
            except LoadError as e:
                errors.append(e)

        # If none worked, raise an error. For T | None with non-null data, 
        # report the error from loading T (first one or deepest).
        if errors:
            # Use the last error which corresponds to the last type tried
            # But we want to report deep inside. Let's use the first error for simplicity
            # Actually, let's raise a union error
            raise LoadError(path, f"Could not load value as any of {args}")
        else:
            if value is not None and none_arg:
                # This shouldn't happen since we checked above
                pass
            raise LoadError(path, f"Value is not None but no union member matched")

    # Handle Literal types
    if origin is typing.Literal:
        literal_values = args
        # Check if value matches any literal (same type and same value)
        for lv in literal_values:
            if isinstance(lv, (int, str, bool)) and type(lv) == type(value) and lv == value:
                return value
        raise LoadError(path, f"Value {value!r} does not match any literal in {args}")

