    if target_type is bool:
        if isinstance(value, bool):
            return value
        else:
            raise LoadError(path, f"Expected bool, got {type(value).__name__}")

    if target_type is int:
        # bool is not accepted for int
        if isinstance(value, bool):
            raise LoadError(path, f"Expected int, got bool")
        if isinstance(value, int):
            return value
        else:
            raise LoadError(path, f"Expected int, got {type(value).__name__}")

    if target_type is float:
        # bool is not accepted for float
        if isinstance(value, bool):
            raise LoadError(path, f"Expected float, got bool")
        if isinstance(value, (int, float)):
            return float(value)
        else:
            raise LoadError(path, f"Expected float, got {type(value).__name__}")

    if target_type is str:
        if isinstance(value, str):
            return value
        else:
            raise LoadError(path, f"Expected str, got {type(value).__name__}")

    # Handle list[T]
    if origin is list:
        if not isinstance(value, list):
            raise LoadError(path, f"Expected list, got {type(value).__name__}")
        if not args:
            return value  # list with no type params
        inner_type = args[0]
        result = []
        for i, item in enumerate(value):
            item_path = f"{path}[{i}]"
            result.append(_load_value(item, inner_type, item_path, globalns, localns))
        return result

    # Handle dict[str, T]
    if origin is dict:
        if not isinstance(value, dict):
            raise LoadError(path, f"Expected dict, got {type(value).__name__}")
        if args:
            key_type = args[0]
            value_type = args[1]
        else:
            key_type = str
            value_type = Any

        # Check key type - JSON keys are always strings
        result = {}
        for k, v in value.items():
            if not isinstance(k, str):
                raise LoadError(path, f"Expected string key, got {type(k).__name__}")
            # Validate key matches key_type (which should be str)
            if key_type is not str:
                try:
                    k = _load_value(k, key_type, path, globalns, localns)
                except LoadError:
                    raise LoadError(path, f"Key {k!r} does not match key type {key_type}")

            v_path = f"{path}.{k}"
            result[k] = _load_value(v, value_type, v_path, globalns, localns)
        return result

    # Handle tuple[T, ...] (variable length)
    if origin is tuple:
        if not isinstance(value, list):
            raise LoadError(path, f"Expected tuple/list, got {type(value).__name__}")

        if not args or args == ((),):
            # Empty tuple
            if value != []:
                raise LoadError(path, f"Expected empty tuple, got non-empty list")
            return ()

        # Check if it's variable length tuple (*args)
        # In Python 3.9+, tuple[T, ...] has args like (T,) and the origin is tuple
        # We need to check if there's an ellipsis
        if len(args) == 1 and args[0] is Ellipsis:
            # Variable length tuple of T
            inner_type = get_args(get_args(target_type)[0])[0] if get_args(target_type) else Any
            # Actually, for tuple[T, ...], args is (T,)
            inner_type = args[0]
            result = []
            for i, item in enumerate(value):
                item_path = f"{path}[{i}]"
                result.append(_load_value(item, inner_type, item_path, globalns, localns))
            return tuple(result)
        else:
            # Fixed length tuple
            if len(value) != len(args):
                raise LoadError(path, f"Expected tuple of length {len(args)}, got {len(value)}")
            result = []
            for i, (item, item_type) in enumerate(zip(value, args)):
                item_path = f"{path}[{i}]"
                result.append(_load_value(item, item_type, item_path, globalns, localns))
            return tuple(result)

    # Handle dataclasses
    if dataclasses.is_dataclass(target_type) and not isinstance(target_type, type):
        raise LoadError(path, f"Expected dataclass, got {target_type}")

    if dataclasses.is_dataclass(target_type):
        if not isinstance(value, dict):
            raise LoadError(path, f"Expected object (dict), got {type(value).__name__}")

        # Get field info
        fields = dataclasses.fields(target_type)
        field_map = {f.name: f for f in fields}

        # Check for unknown keys
        for key in value:
            if key not in field_map:
                raise LoadError(path, f"Unknown key: {key}")

        # Build instance
        init_kwargs = {}
        non_init_fields = []

        for field in fields:
            field_path = f"{path}.{field.name}"
            if field.name in value:
                try:
                    init_kwargs[field.name] = _load_value(value[field.name], field.type, field_path, globalns, localns)
                except LoadError as e:
                    raise
            else:
                # Missing key
                if field.default is not dataclasses.MISSING:
                    init_kwargs[field.name] = field.default
                elif field.default_factory is not dataclasses.MISSING:
                    init_kwargs[field.name] = field.default_factory()
                else:
                    raise LoadError(field_path, f"Missing required field")

        return target_type(**init_kwargs)

    # Fallback: try to create instance directly
    try:
        if isinstance(value, target_type):
            return value
        return target_type(value)
    except Exception as e:
        raise LoadError(path, f"Cannot convert {type(value).__name__} to {target_type.__name__}: {e}")


def load(cls: type, data: Any) -> Any:
    """Build an instance of a dataclass type from JSON-like data."""

    # Get resolved type hints for the dataclass
    try:
        hints = get_type_hints(cls)
    except Exception as e:
        raise LoadError("$", f"Cannot resolve type hints for {cls.__name__}: {e}")

    # Replace field types with resolved hints where available
    globalns = getattr(cls, '__globals__', None)
    localns = {}

    return _load_value(data, cls, "$", globalns, localns)
