#!/usr/bin/env bash
set -euo pipefail

# Check for missing input files
files=("$@")
if [ ${#files[@]} -eq 0 ]; then
    echo "Usage: solution.sh LOGFILE..." >&2
    exit 1
fi

for f in "${files[@]}"; do
    if [ "$f" != "-" ] && [ ! -f "$f" ]; then
        echo "solution.sh: $f: No such file or directory" >&2
        exit 1
    fi
done

# Create a temporary directory for intermediate files
tmpdir=$(mktemp -d)
trap 'rm -rf "$tmpdir"' EXIT

# Function to cat files appropriately
cat_inputs() {
    for f in "${files[@]}"; do
        if [ "$f" = "-" ]; then
            cat
        elif [[ "$f" == *.gz ]]; then
            zcat "$f"
        else
            cat "$f"
        fi
    done
}

# Parse the logs with awk
cat_inputs | awk '
BEGIN {
    malformed = 0
    requests = 0
}
{
    line = $0

    # Extract IP (first field up to first space)
    ip_end = index(line, " ")
    if (ip_end == 0) {
        malformed++
        next
    }
    ip = substr(line, 1, ip_end - 1)
    rest = substr(line, ip_end + 1)

    # Extract ident (up to next space)
