            } else {
                print "Error: Unknown column " col_spec > "/dev/stderr"
                exit 3
            }
        }

        # Check if target index is within bounds of header
        if (target_idx < 1 || target_idx > num_f) {
             print "Error: Column index out of range" > "/dev/stderr"
             exit 3
        }
    } else {
        # Data row
        # If fewer fields than header, treat missing as empty
        val = ""
        if (target_idx <= num_f) {
            val = rec_fields[target_idx]
        }

        if (sort_flag == 1) {
            # Numeric aggregation
            # Check if numeric: optional sign, then digits with optional decimal point.
            # Matches: 123, -123, 1.23, -.5, .5, 1., etc.
            # Pattern: ^[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)$
            if (val ~ /^[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)$/) {
                num = val + 0
                count++
                sum_val += num

                if (count == 1) {
                    min_val = num
                    max_val = num
                } else {
                    if (num < min_val) min_val = num
                    if (num > max_val) max_val = num
                }
            }
        } else {
            # Print value, replacing embedded newlines with literal \n
            gsub(/\n/, "\\n", val)
            print val
        }
    }

    # Reset buffer for next record
    buffer = ""
}

END {
    if (sort_flag == 1) {
        if (count == 0) {
            print "count=0"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", count, sum_val, min_val, max_val
        }
    } else {
        # If we ended with an unterminated quote (buffer not empty and in_quote_state is 1)
        if (in_quote_state && buffer != "") {
            print "Error: Unterminated quote" > "/dev/stderr"
            exit 4
        }
    }
}
'

exit $?
